export function words(key,lang="en",values={}) {
  const pair=messages[key]||messages.internal;
  return pair[lang==="ko"?1:0].replace(/\{([a-zA-Z_ ]+)\}/g,(all,name)=>Object.hasOwn(values,name)?String(values[name]):all);
}
